const commits = $input.all().filter(i => i.json.workflow === 'commits') || [];
const issues = $input.all().filter(i => i.json.workflow === 'issues') || [];
const prs = $input.all().filter(i => i.json.workflow === 'prs') || [];

const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - weekStart.getDay());
weekStart.setHours(0,0,0,0);

const mergedPRs = prs.filter(p => 
  p.json.merged_at && new Date(p.json.merged_at) >= weekStart
);

const summary = {
  repo: $env.GITHUB_REPO || 'unknown',
  week: `${weekStart.toISOString().split('T')[0]} to ${new Date().toISOString().split('T')[0]}`,
  stats: {
    commits: commits.length,
    closed_issues: issues.length,
    merged_prs: mergedPRs.length
  },
  top_commits: commits.slice(0, 10).map(c => ({
    message: c.json.commit?.message?.split('\n')[0] || '',
    author: c.json.commit?.author?.name || c.json.author?.login || 'unknown',
    date: c.json.commit?.author?.date || '',
    url: c.json.html_url || ''
  })),
  top_issues: issues.slice(0, 5).map(i => ({
    title: i.json.title || '',
    number: i.json.number || 0,
    url: i.json.html_url || ''
  })),
  top_prs: mergedPRs.slice(0, 5).map(p => ({
    title: p.json.title || '',
    number: p.json.number || 0,
    author: p.json.user?.login || 'unknown',
    url: p.json.html_url || ''
  }))
};

return [{ json: summary }];

parameters.value:
=[
  {
    "role": "user",
    "content": `Generate a narrative weekly development summary for repository {{ $json.repo }} covering {{ $json.week }}.

## Stats
- Commits: {{ $json.stats.commits }}
- Closed Issues: {{ $json.stats.closed_issues }}
- Merged PRs: {{ $json.stats.merged_prs }}

## Top Commits
{{#each $json.top_commits}}
- {{this.message}} ({{this.author}}, {{this.date}})
{{/each}}

## Closed Issues
{{#each $json.top_issues}}
- #{{this.number}}: {{this.title}}
{{/each}}

## Merged PRs
{{#each $json.top_prs}}
- #{{this.number}}: {{this.title}} by @{{this.author}}
{{/each}}

Write a 2-3 paragraph narrative summary in English (or {{ $env.LANGUAGE || 'EN' }}). Start with an engaging opening sentence. Include a 'Key Highlights' section. End with a forward-looking closing remark.`
    }
  }
]

